ody',                    'name' => 'testimonial_body',                    'type' => 'wysiwyg',                    'instructions' => 'Main text for the testimonial',                    'required' => 0,                    'conditional_logic' => 0,                    'wrapper' => array(                        'width' => '',                        'class' => '',                        'id' => '',                    ),                    'default_value' => '',                    'tabs' => 'all',              // 'all' | 'visual' | 'text'                    'toolbar' => 'basic',         // 'full' | 'basic'                    'media_upload' => 0,          // set to 1 if you want media button                    'delay' => 0,                ),                array(                    'key' => 'field_testimonial_image',                    'label' => 'Testimonial image',                    'name' => 'testimonial_image',                    'type' => 'image',                    'instructions' => 'Optional image to display alongside the testimonial.',                    'required' => 0,                    'conditional_logic' => 0,                    'wrapper' => array(                        'width' => '',                        'class' => '',                        'id' => '',                    ),                    'return_format' => 'array',   // 'array' | 'id' | 'url'                    'preview_size' => 'medium',                    'library' => 'all',                    'min_width' => 0,                    'min_height' => 0,                    'min_size' => '',                    'max_width' => 0,                    'max_height' => 0,                    'max_size' => '',                    'mime_types' => 'jpg,jpeg,png,webp',                ),                array(                    'key' => 'field_testimonial_citation',                    'label' => 'Testimonial citation',                    'name' => 'testimonial_citation',  